solutionCode:
class Counter {
    var count = 0

    fun increment() {
        count = count + 1
    }

    fun decrement() {
        count = count - 1
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testInitialCount() {
        val counter = Counter()
        Assert.assertEquals(0, counter.count)
    }

    @Test
    fun testIncrement() {
        val counter = Counter()
        counter.increment()
        counter.increment()
        Assert.assertEquals(2, counter.count)
    }

    @Test
    fun testDecrement() {
        val counter = Counter()
        counter.increment()
        counter.increment()
        counter.decrement()
        Assert.assertEquals(1, counter.count)
    }

    @Test
    fun testDecrementBelowZero() {
        val counter = Counter()
        counter.decrement()
        Assert.assertEquals(-1, counter.count)
    }
}
